sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...

var keywords = ['RE:','re:','re:'];
var flag = " ";
var subject = inputs.subject;
for(i in keywords)
{
    if(subject.startsWith(keywords[i]))
    {
        outputs.flag = 'false';
        break;
    }
    else{
        outputs.flag = 'true';
    }
}

})(inputs, outputs);

